-- The remaining 5 Mystery Shopper checklists (Dine In, Express, Figaro,
-- Tien Ma's, Koobideh), rebuilt from completed samples the same way
-- Delivery was — the master "All Brand" workbook is no longer available,
-- and a filled-in copy carries the same item labels/points as the blank
-- template. 0-point "group header" rows excluded (not real yes/no
-- questions, just a label for their own sub-items).
--
-- All QA-only (requires_audit_type), point-weighted, pass threshold 92.5%
-- per standing rule, supports_excel_import for the upcoming import
-- feature, brand-locked via store_restrictions resolved dynamically by
-- brand_name at migration time (covers whatever stores are active then).

INSERT INTO public.audit_templates (
  id, title, description, sections, is_active, template_group, active_ticket,
  pass_threshold, requires_audit_type, requires_visit_number, requires_commitment_date,
  requires_department, has_time_restriction, available_from_time, available_to_time,
  supports_excel_import, store_restrictions, created_date, updated_date
)
SELECT
  gen_random_uuid()::text,
  'Angel''s Pizza Mystery Shopper (Dine In)',
  'Mystery shopper evaluation of the Angel''s Pizza dine-in experience: service upon entry, order taking, table service, product quality, dine-in area, and general observation.',
  '[{"id":"msdine_s1","title":"When you entered the store did the Service staff:","items":[{"id":"msdine_s1_i1","label":"Did the staff greet you warmly?\n\u201cGood morning / afternoon / evening, sir/ ma\u2019am. \nWelcome to Angel\u2019s Pizza\u201d.","photo_required":false,"pts":5},{"id":"msdine_s1_i2","label":"Was the greeting recited formally?","photo_required":false,"pts":5},{"id":"msdine_s1_i3","label":"Was your presence acknowledged?\nDid the staff pause to acknowledge your presence?\nDid the staff stop what he was doing and pay attention to your needs?","photo_required":false,"pts":5}]},{"id":"msdine_s2","title":"When taking of your order, did Cashier:","items":[{"id":"msdine_s2_i1","label":"Did the cashier greet you with a smile?","photo_required":false,"pts":5},{"id":"msdine_s2_i2","label":"Did the cashier suggest and recommend any new product?","photo_required":false,"pts":5},{"id":"msdine_s2_i3","label":"Did the cashier make any up-selling?","photo_required":false,"pts":5},{"id":"msdine_s2_i4","label":"Cashier appears to be knowledgeable about\nThe menu items?","photo_required":false,"pts":5},{"id":"msdine_s2_i5","label":"Did the cashier repeat your orders?","photo_required":false,"pts":5},{"id":"msdine_s2_i6","label":"Did the cashier notify you that a certain order would take long?\nEx: Pizza takes 30 minutes","photo_required":false,"pts":5},{"id":"msdine_s2_i7","label":"Did the cashier acknowledge the acceptance \nof your payment and the value?\n\u201cSir / Ma\u2019am. I received <amount> pesos\u201d","photo_required":false,"pts":5},{"id":"msdine_s2_i8","label":"Did the Cashier give POS Receipt?","photo_required":false,"pts":5},{"id":"msdine_s2_i9","label":"Did the Cashier give exact change?","photo_required":false,"pts":5},{"id":"msdine_s2_i10","label":"Did the cashier say \u201cThank you\u201d after the transaction and give you a number/buzzer?\nexplain that your order will be sent to your \ntable and/or give you a table number?","photo_required":false,"pts":1},{"id":"msdine_s2_i11","label":"Cashier wearing complete uniform?\n(Maroon polo, black slacks, hairnet,\nApron, black shoes and name plate)","photo_required":false,"pts":5},{"id":"msdine_s2_i12","label":"Was the Cashier friendly and approachable?","photo_required":false,"pts":5}]},{"id":"msdine_s3","title":"After being seated, did the service staff:","items":[{"id":"msdine_s3_i1","label":"Did the staff extend a warm greeting and convery the feelung that you were a valued guest?","photo_required":false,"pts":5},{"id":"msdine_s3_i2","label":"Did the staff announce his/her presence?","photo_required":false,"pts":5},{"id":"msdine_s3_i3","label":"Were your beverages served promptly?","photo_required":false,"pts":5},{"id":"msdine_s3_i4","label":"Serve food 10 to 15 minutes?\nExcept for Pizza.","photo_required":false,"pts":5},{"id":"msdine_s3_i5","label":"Did the staff ask you if he has served all  your orders?","photo_required":false,"pts":5},{"id":"msdine_s3_i6","label":"If your order took for 20 mins or more, did the employee apologize?","photo_required":false,"pts":5},{"id":"msdine_s3_i7","label":"Does the service station has spoon, fork, knife, hotsauce/ketchup, salt and pepper and water pitcher/water dispenser?","photo_required":false,"pts":5},{"id":"msdine_s3_i8","label":"Did the staff remain attentive throughout\nthe dining experience?","photo_required":false,"pts":5},{"id":"msdine_s3_i9","label":"Did the staff excused himself?","photo_required":false,"pts":5},{"id":"msdine_s3_i10","label":"When you complained about your food, did staff apologize and say he will fix it/ change it?","photo_required":false,"pts":5},{"id":"msdine_s3_i11","label":"Was the Server wearing complete uniform?\n(Maroon polo, black slacks, hairnet,\nApron, black shoes and name plate)","photo_required":false,"pts":5},{"id":"msdine_s3_i12","label":"Was the server approachable &\n professional in their manner?","photo_required":false,"pts":5}]},{"id":"msdine_s4","title":"Product Quality","items":[{"id":"msdine_s4_i1","label":"Was your food/pizza temperature appropriate?","photo_required":false,"pts":5},{"id":"msdine_s4_i2","label":"Did it taste good?","photo_required":false,"pts":5},{"id":"msdine_s4_i3","label":"Did it smell good?","photo_required":false,"pts":5},{"id":"msdine_s4_i4","label":"Was your beverage full flavored?","photo_required":false,"pts":5},{"id":"msdine_s4_i5","label":"Was all food served promptly?","photo_required":false,"pts":5},{"id":"msdine_s4_i6","label":"Were your food served according to its \nStandard presentation? \n(Appearance and serving dish)","photo_required":false,"pts":5}]},{"id":"msdine_s5","title":"Dine in Area:","items":[{"id":"msdine_s5_i1","label":"Is the Outlet clean and orderly? Floors is clean & litter free?","photo_required":false,"pts":5},{"id":"msdine_s5_i2","label":"Tables and chairs are set orderly?","photo_required":false,"pts":5},{"id":"msdine_s5_i3","label":"Windows and other glass panels are clean?","photo_required":false,"pts":5},{"id":"msdine_s5_i4","label":"Noise level is acceptable?","photo_required":false,"pts":1},{"id":"msdine_s5_i5","label":"Music volume & type is appropriate?","photo_required":false,"pts":1},{"id":"msdine_s5_i6","label":"Lighting is appropriate?","photo_required":false,"pts":1},{"id":"msdine_s5_i7","label":"Signs are visible, attractive, maintained?","photo_required":false,"pts":1},{"id":"msdine_s5_i8","label":"Were the advertising material and collaterals in good condition and displayed properly?","photo_required":false,"pts":1},{"id":"msdine_s5_i9","label":"Restrooms is clean, litter free on the floors and has no odor? (if applicable)","photo_required":false,"pts":5},{"id":"msdine_s5_i10","label":"Paper towels and toilet paper is stocked? (if applicable)","photo_required":false,"pts":1},{"id":"msdine_s5_i11","label":"Toilets / sinks is clean \u2013 good condition? (if applicable)","photo_required":false,"pts":1},{"id":"msdine_s5_i12","label":"Soap dispensers is stocked & functional? (if applicable)","photo_required":false,"pts":1},{"id":"msdine_s5_i13","label":"Is the store ambient is appropriate/ACU are functioning?","photo_required":false,"pts":5},{"id":"msdine_s5_i14","label":"Is outlet free from insect/pest infestation?","photo_required":false,"pts":5},{"id":"msdine_s5_i15","label":"Overall facilities well maintained?","photo_required":false,"pts":5}]},{"id":"msdine_s6","title":"General Observation","items":[{"id":"msdine_s6_i1","label":"Manager is visible at the Store?","photo_required":false,"pts":5},{"id":"msdine_s6_i2","label":"Did staff clear the table properly and efficiently?","photo_required":false,"pts":5},{"id":"msdine_s6_i3","label":"When you say thank you, do the staff respond with \u201cMy Pleasure\u201d?","photo_required":false,"pts":5},{"id":"msdine_s6_i4","label":"Was staff pleasant and smiling during your stay?","photo_required":false,"pts":5},{"id":"msdine_s6_i5","label":"Did staff thank you politely and tell you to visit again?\n\u201cThank you for coming. We hope to see you soon\u201d","photo_required":false,"pts":5},{"id":"msdine_s6_i6","label":"Did the overall dining experience meet or exceed your expectations?","photo_required":false,"pts":5},{"id":"msdine_s6_i7","label":"Based on this dining experience, would you return as a paying customer?","photo_required":false,"pts":5}]}]'::jsonb,
  true, 'angels-pizza', false,
  92.5, true, false, false,
  false, false, '', '',
  true,
  (
    SELECT jsonb_agg(jsonb_build_object('brand_id', b.id, 'brand_name', b.brand_name, 'store_id', s.id, 'store_name', s.store_name))
    FROM public.stores s
    JOIN public.brands b ON b.id = s.brand_id
    WHERE b.brand_name = 'Angels Pizza' AND coalesce(s.is_active, true) AND coalesce(s.kind, 'store') = 'store'
  ),
  now(), now()
WHERE NOT EXISTS (
  SELECT 1 FROM public.audit_templates WHERE title = 'Angel''s Pizza Mystery Shopper (Dine In)'
);


INSERT INTO public.audit_templates (
  id, title, description, sections, is_active, template_group, active_ticket,
  pass_threshold, requires_audit_type, requires_visit_number, requires_commitment_date,
  requires_department, has_time_restriction, available_from_time, available_to_time,
  supports_excel_import, store_restrictions, created_date, updated_date
)
SELECT
  gen_random_uuid()::text,
  'Angel''s Pizza Express Mystery Shopper',
  'Mystery shopper evaluation of the Angel''s Pizza Express experience: greetings, order taking, product quality, store appearance, and general observation.',
  '[{"id":"msapex_s1","title":"GREETINGS","items":[{"id":"msapex_s1_i1","label":"Did the staff greet you warmly?\n\u201cGood morning / afternoon / evening, sir/ ma\u2019am. \nWelcome to Angel\u2019s Pizza\u201d.","photo_required":false,"pts":5},{"id":"msapex_s1_i2","label":"Was the greeting recited formally?","photo_required":false,"pts":5},{"id":"msapex_s1_i3","label":"Was your presence acknowledged?\nDid the staff pause to acknowledge your presence?\nDid the staff stop what he was doing and pay attention to your needs?","photo_required":false,"pts":5}]},{"id":"msapex_s2","title":"ORDER TAKING","items":[{"id":"msapex_s2_i1","label":"Did the cashier greet you with a smile?","photo_required":false,"pts":5},{"id":"msapex_s2_i2","label":"Did the cashier suggest and recommend any new product?","photo_required":false,"pts":5},{"id":"msapex_s2_i3","label":"Did the cashier make any up-selling?","photo_required":false,"pts":5},{"id":"msapex_s2_i4","label":"Cashier appears to be knowledgeable about\nthe menu items?","photo_required":false,"pts":5},{"id":"msapex_s2_i5","label":"Did the cashier repeat your orders?","photo_required":false,"pts":5},{"id":"msapex_s2_i6","label":"Did the cashier notify you that a certain order would take long?\nEx: Pizza takes 3-5 minutes","photo_required":false,"pts":5},{"id":"msapex_s2_i7","label":"Did the cashier acknowledge the acceptance  of your payment and the value?","photo_required":false,"pts":5},{"id":"msapex_s2_i8","label":"Did the cashier say \u201cThank you\u201d after the transaction and give you a table number/buzzer?","photo_required":false,"pts":1},{"id":"msapex_s2_i9","label":"Did the Cashier give POS Receipt?","photo_required":false,"pts":5},{"id":"msapex_s2_i10","label":"Did the Cashier give exact change?","photo_required":false,"pts":5},{"id":"msapex_s2_i11","label":"Cashier wearing complete uniform?\n(Maroon polo, Black slacks, Hairnet, Apron, Black shoes and Name plate)","photo_required":false,"pts":5},{"id":"msapex_s2_i12","label":"Was the Cashier friendly and approachable?","photo_required":false,"pts":5}]},{"id":"msapex_s3","title":"PRODUCT QUALITY","items":[{"id":"msapex_s3_i1","label":"Was your food temperature appropriate?","photo_required":false,"pts":5},{"id":"msapex_s3_i2","label":"Did it taste good?","photo_required":false,"pts":5},{"id":"msapex_s3_i3","label":"Was appearance good? Do the toppings \nevenly distributed?","photo_required":false,"pts":5},{"id":"msapex_s3_i4","label":"Was the pizza properly/evenly cut?","photo_required":false,"pts":5},{"id":"msapex_s3_i5","label":"Was all food served promptly?","photo_required":false,"pts":5},{"id":"msapex_s3_i6","label":"Serve pizza 3 to 5 minutes?","photo_required":false,"pts":5},{"id":"msapex_s3_i7","label":"If your order took for 6 mins or more, \ndid the employee apologize?","photo_required":false,"pts":5},{"id":"msapex_s3_i8","label":"Did you receive your correct food order?","photo_required":false,"pts":5},{"id":"msapex_s3_i9","label":"When you complained about your food, \ndid staff apologize and say he will fix it/\nchange it?","photo_required":false,"pts":5}]},{"id":"msapex_s4","title":"STORE APPEARANCE","items":[{"id":"msapex_s4_i1","label":"Is the Outlet clean and orderly? Floors clean & litter free?","photo_required":false,"pts":5},{"id":"msapex_s4_i2","label":"Noise level acceptable?","photo_required":false,"pts":1},{"id":"msapex_s4_i3","label":"Lighting was appropriate?","photo_required":false,"pts":1},{"id":"msapex_s4_i4","label":"Overall facilities well maintained?","photo_required":false,"pts":5},{"id":"msapex_s4_i5","label":"Signs visible, attractive, maintained?","photo_required":false,"pts":1},{"id":"msapex_s4_i6","label":"Is the store ambient is appropriate/ACU are functioning?","photo_required":false,"pts":5},{"id":"msapex_s4_i7","label":"Is outlet free from insect/pest infestation?","photo_required":false,"pts":5},{"id":"msapex_s4_i8","label":"Were the advertising material and collaterals in good condition and displayed properly?","photo_required":false,"pts":1}]},{"id":"msapex_s5","title":"General Observation","items":[{"id":"msapex_s5_i1","label":"When you say thank you, do the staff respond with \u201cMy Pleasure\u201d?","photo_required":false,"pts":5},{"id":"msapex_s5_i2","label":"Did the staff appear neat and professional in their appearance?\n(wearing complete uniform with hairnet)","photo_required":false,"pts":5},{"id":"msapex_s5_i3","label":"Did staff clear the table properly and efficiently?","photo_required":false,"pts":5},{"id":"msapex_s5_i4","label":"Was staff pleasant and smiling during your stay?","photo_required":false,"pts":5},{"id":"msapex_s5_i5","label":"Did staff thank you politely and tell you to visit again?\n\u201cThank you for coming. We hope to see you soon\u201d","photo_required":false,"pts":5},{"id":"msapex_s5_i6","label":"Did the overall dining experience meet or exceed your expectations?","photo_required":false,"pts":5},{"id":"msapex_s5_i7","label":"Based on this dining experience, would you return as a paying customer?","photo_required":false,"pts":5}]}]'::jsonb,
  true, 'angels-pizza-express', false,
  92.5, true, false, false,
  false, false, '', '',
  true,
  (
    SELECT jsonb_agg(jsonb_build_object('brand_id', b.id, 'brand_name', b.brand_name, 'store_id', s.id, 'store_name', s.store_name))
    FROM public.stores s
    JOIN public.brands b ON b.id = s.brand_id
    WHERE b.brand_name = 'Angels Pizza Express' AND coalesce(s.is_active, true) AND coalesce(s.kind, 'store') = 'store'
  ),
  now(), now()
WHERE NOT EXISTS (
  SELECT 1 FROM public.audit_templates WHERE title = 'Angel''s Pizza Express Mystery Shopper'
);


INSERT INTO public.audit_templates (
  id, title, description, sections, is_active, template_group, active_ticket,
  pass_threshold, requires_audit_type, requires_visit_number, requires_commitment_date,
  requires_department, has_time_restriction, available_from_time, available_to_time,
  supports_excel_import, store_restrictions, created_date, updated_date
)
SELECT
  gen_random_uuid()::text,
  'Figaro Mystery Shopper',
  'Mystery shopper evaluation of the Figaro Coffee experience: service upon entry, order taking, table service, product quality, bar area, manager, and general observation.',
  '[{"id":"msfigaro_s1","title":"When you entered the store did the Service staff:","items":[{"id":"msfigaro_s1_i1","label":"Did the staff greet you warmly?\n\u201cGood morning / afternoon / evening, sir/ ma\u2019am. \nWelcome to Figaro\u201d.","photo_required":false,"pts":5},{"id":"msfigaro_s1_i2","label":"Was the greeting recited formally?","photo_required":false,"pts":5},{"id":"msfigaro_s1_i3","label":"Was your presence acknowledged?\nDid the staff pause to acknowledge your presence?\nDid the staff stop what he was doing and pay attention to your needs?","photo_required":false,"pts":5}]},{"id":"msfigaro_s2","title":"When taking of your order, did Cashier:","items":[{"id":"msfigaro_s2_i1","label":"Did the cashier greet you with a smile?","photo_required":false,"pts":5},{"id":"msfigaro_s2_i2","label":"Did the cashier suggest and recommend any new product?","photo_required":false,"pts":5},{"id":"msfigaro_s2_i3","label":"Did the cashier make any up-selling?","photo_required":false,"pts":5},{"id":"msfigaro_s2_i4","label":"Cashier appears to be knowledgeable about\nThe menu items?","photo_required":false,"pts":5},{"id":"msfigaro_s2_i5","label":"Did the cashier repeat your orders?","photo_required":false,"pts":5},{"id":"msfigaro_s2_i6","label":"Did the cashier notify you that a certain order would take long?\nEx: Pasta takes 10-15 minutes","photo_required":false,"pts":5},{"id":"msfigaro_s2_i7","label":"Did the cashier acknowledge the acceptance  of your payment and the value?\n\u201cThank you sir / ma\u2019am. I received <amount>","photo_required":false,"pts":5},{"id":"msfigaro_s2_i8","label":"Did the cashier say \u201cThank you\u201d, give you a table number and explain that your order will be sent to your table?","photo_required":false,"pts":1},{"id":"msfigaro_s2_i9","label":"Did the Cashier give O.R and exact change?","photo_required":false,"pts":5},{"id":"msfigaro_s2_i10","label":"Cashier wearing complete uniform, friendly and approachable?","photo_required":false,"pts":5}]},{"id":"msfigaro_s3","title":"After being seated, did the service staff:","items":[{"id":"msfigaro_s3_i1","label":"Did the staff arrive within two to three\nminutes to set up your table?","photo_required":false,"pts":5},{"id":"msfigaro_s3_i2","label":"Did the staff extend a warm greeting and introduce themselves by name?","photo_required":false,"pts":5},{"id":"msfigaro_s3_i3","label":"Did the staff convey the feeling that\nYou were a valued guest?","photo_required":false,"pts":1},{"id":"msfigaro_s3_i4","label":"Was your table properly set up?","photo_required":false,"pts":5},{"id":"msfigaro_s3_i5","label":"Did the staff announce his/her presence?\nDid the staff say, \u201cExcuse me sir / ma\u2019am \n(use guest name if you are familiar)\nyou ordered for <item/s>\u201d, while he / she \nis serving it on your table?","photo_required":false,"pts":5},{"id":"msfigaro_s3_i6","label":"Serve drinks 3 to 5 minutes?","photo_required":false,"pts":5},{"id":"msfigaro_s3_i7","label":"Were your beverages served promptly","photo_required":false,"pts":5},{"id":"msfigaro_s3_i8","label":"Serve food 10 to 15 minutes?","photo_required":false,"pts":5},{"id":"msfigaro_s3_i9","label":"Did you receive your correct food order?","photo_required":false,"pts":5},{"id":"msfigaro_s3_i10","label":"Did the staff ask you if he has served all \nyour orders?\n\u201cExcuse me sir / ma\u2019am, have I served \nall your orders?\u201d","photo_required":false,"pts":5},{"id":"msfigaro_s3_i11","label":"Did the staff anticipate customer needs?\nEx. Extra plate, extra utensils, salt, pepper,\ncheese, and other condiments (especially for\n sharing/group)","photo_required":false,"pts":5},{"id":"msfigaro_s3_i12","label":"Did the staff thanked you and excused \nhimself?","photo_required":false,"pts":5},{"id":"msfigaro_s3_i13","label":"If your order took for 15 mins or more, \ndid the employee apologize?","photo_required":false,"pts":5},{"id":"msfigaro_s3_i14","label":"When you complained about your food, \ndid staff apologize and say he will fix it/ change it?\n\u201cI apologize that you are unhappy, may I change you order? Reheat/ add more syrup?\u201d","photo_required":false,"pts":5},{"id":"msfigaro_s3_i15","label":"Did the staff remain attentive throughout\nThe dining experience?","photo_required":false,"pts":5},{"id":"msfigaro_s3_i16","label":"Was the Server wearing complete uniform\nIncluding name tag?","photo_required":false,"pts":5},{"id":"msfigaro_s3_i17","label":"Was the server approachable & professional in their manner?","photo_required":false,"pts":5}]},{"id":"msfigaro_s4","title":"During your meal, did your server:","items":[{"id":"msfigaro_s4_i1","label":"Did staff check back on you to ensure that your meal was satisfactory? Did he announce his presence?\n\u201cExcuse me sir / ma\u2019am, how are you enjoying your food / coffee / drink / meal?\u201d","photo_required":false,"pts":5},{"id":"msfigaro_s4_i2","label":"Did the server offer refills of water?(if needed)","photo_required":false,"pts":1},{"id":"msfigaro_s4_i3","label":"When you are waving to a staff, does he acknowledge your call and manage your expectation?","photo_required":false,"pts":5}]},{"id":"msfigaro_s5","title":"Product Quality","items":[{"id":"msfigaro_s5_i1","label":"Was your food/pizza temperature appropriate?","photo_required":false,"pts":5},{"id":"msfigaro_s5_i2","label":"Did it taste good?","photo_required":false,"pts":5},{"id":"msfigaro_s5_i3","label":"Was appearance good?","photo_required":false,"pts":5},{"id":"msfigaro_s5_i4","label":"Was your beverage full flavored\n (not watery or flat)","photo_required":false,"pts":5},{"id":"msfigaro_s5_i5","label":"Was all food served promptly?","photo_required":false,"pts":5},{"id":"msfigaro_s5_i6","label":"Were your food served according to its \nStandard presentation? \n(Appearance and serving dish)","photo_required":false,"pts":5}]},{"id":"msfigaro_s6","title":"At the completion of your entr\u00e9e, did your server:","items":[{"id":"msfigaro_s6_i1","label":"Did the staff clear table of soiled dishes or napkins?\n\u201cExcuse me sir / ma\u2019am would you like me to remove the dishes and table napkins?\u201d","photo_required":false,"pts":5},{"id":"msfigaro_s6_i2","label":"Did staff clear the table properly and efficiently?\nPay particular attention to how he holds the glasses (in the body and not in the rim), where does he put the utensils (not inside the glass but on the side of the tray), stacking of cups/ saucers and paper napkins (should not be stuffed into glasses or cups).","photo_required":false,"pts":5},{"id":"msfigaro_s6_i3","label":"Before staff left, did he ask if he can get you anything else?\n\u201cWould you like me to get you something else?","photo_required":false,"pts":5},{"id":"msfigaro_s6_i4","label":"Did staff excuse him/herself?\n\u201cExcuse me\u201d","photo_required":false,"pts":1}]},{"id":"msfigaro_s7","title":"Upon leaving the Store:","items":[{"id":"msfigaro_s7_i1","label":"Did staff thank you politely?\nThank you sir / ma\u2019am, we hope you enjoyed your visit. Have a wonderful day (if morning), enjoy the rest of the afternoon/ evening.\u201d","photo_required":false,"pts":5},{"id":"msfigaro_s7_i2","label":"Did staff tell you to visit again?\n\u201c We hope to see you soon.\u201d","photo_required":false,"pts":1}]},{"id":"msfigaro_s8","title":"Regarding the Bar area:","items":[{"id":"msfigaro_s8_i1","label":"Did the Barista appear neat and professional in their appearance?\n(wearing complete uniform with hairnet)","photo_required":false,"pts":5}]},{"id":"msfigaro_s9","title":"Regarding the Manager:","items":[{"id":"msfigaro_s9_i1","label":"Was the Manager interacting with and directing the staff?","photo_required":false,"pts":5},{"id":"msfigaro_s9_i2","label":"Was the Manager visiting tables to inquire about satisfaction?","photo_required":false,"pts":5},{"id":"msfigaro_s9_i3","label":"Did the Manager visit your table?","photo_required":false,"pts":1}]},{"id":"msfigaro_s10","title":"After being seated, did the service staff:","items":[{"id":"msfigaro_s10_i1","label":"Is the Outlet clean and orderly? Floors clean & litter free?","photo_required":false,"pts":5},{"id":"msfigaro_s10_i2","label":"Tables and chairs set orderly?","photo_required":false,"pts":5},{"id":"msfigaro_s10_i3","label":"Noise level acceptable?","photo_required":false,"pts":1},{"id":"msfigaro_s10_i4","label":"Music volume & type appropriate?","photo_required":false,"pts":1},{"id":"msfigaro_s10_i5","label":"Windows and other glass panels are clean?","photo_required":false,"pts":5},{"id":"msfigaro_s10_i6","label":"Lighting was appropriate?","photo_required":false,"pts":1},{"id":"msfigaro_s10_i7","label":"Restrooms clean, litter free floors? (if applicable)","photo_required":false,"pts":1},{"id":"msfigaro_s10_i8","label":"Paper towels and toilet paper stocked? (if applicable)","photo_required":false,"pts":1},{"id":"msfigaro_s10_i9","label":"Toilets, sinks clean \u2013 good condition? (if applicable)","photo_required":false,"pts":1},{"id":"msfigaro_s10_i10","label":"Soap dispensers stocked & functional? (if applicable)","photo_required":false,"pts":1},{"id":"msfigaro_s10_i11","label":"Overall facilities well maintained?","photo_required":false,"pts":5},{"id":"msfigaro_s10_i12","label":"Signs visible, attractive, maintained?","photo_required":false,"pts":1},{"id":"msfigaro_s10_i13","label":"If the outlet has smoking area does the area free from ashes and cigarette butts? (max3 butts on astray) - (if applicable)","photo_required":false,"pts":1},{"id":"msfigaro_s10_i14","label":"Is outlet free from insect/pest infestation?","photo_required":false,"pts":5},{"id":"msfigaro_s10_i15","label":"Were the advertising material and collaterals in good condition and displayed properly?","photo_required":false,"pts":1},{"id":"msfigaro_s10_i16","label":"Did the pastries in display case appear fresh and appetizing?","photo_required":false,"pts":5}]},{"id":"msfigaro_s11","title":"General Observation","items":[{"id":"msfigaro_s11_i1","label":"When you say thank you, do the staff respond with \u201cMy Pleasure\u201d?","photo_required":false,"pts":5},{"id":"msfigaro_s11_i2","label":"Was staff pleasant and smiling during your stay?","photo_required":false,"pts":5},{"id":"msfigaro_s11_i3","label":"Did the overall dining experience meet or exceed your expectations?","photo_required":false,"pts":5},{"id":"msfigaro_s11_i4","label":"Based on this dining experience, would you return as a paying customer?","photo_required":false,"pts":5}]}]'::jsonb,
  true, 'figaro', false,
  92.5, true, false, false,
  false, false, '', '',
  true,
  (
    SELECT jsonb_agg(jsonb_build_object('brand_id', b.id, 'brand_name', b.brand_name, 'store_id', s.id, 'store_name', s.store_name))
    FROM public.stores s
    JOIN public.brands b ON b.id = s.brand_id
    WHERE b.brand_name = 'Figaro Coffee' AND coalesce(s.is_active, true) AND coalesce(s.kind, 'store') = 'store'
  ),
  now(), now()
WHERE NOT EXISTS (
  SELECT 1 FROM public.audit_templates WHERE title = 'Figaro Mystery Shopper'
);


