el":"Are Restrooms clean, litter free floors?","photo_required":false,"pts":1},{"id":"mstienma_s9_i8","label":"Paper towels and toilet paper stocked? (if applicable)","photo_required":false,"pts":1},{"id":"mstienma_s9_i9","label":"Toilets, sinks clean \u2013 good condition? (if applicable)","photo_required":false,"pts":1},{"id":"mstienma_s9_i10","label":"Soap dispensers stocked & functional? (if applicable)","photo_required":false,"pts":1},{"id":"mstienma_s9_i11","label":"Overall facilities well maintained?","photo_required":false,"pts":5},{"id":"mstienma_s9_i12","label":"Signs visible, attractive, maintained?","photo_required":false,"pts":1},{"id":"mstienma_s9_i13","label":"If the outlet has smoking area does the area free from ashes and cigarette butts? (max3 butts on astray) - (if applicable)","photo_required":false,"pts":1},{"id":"mstienma_s9_i14","label":"Is outlet free from insect/pest infestation?","photo_required":false,"pts":5},{"id":"mstienma_s9_i15","label":"Were the advertising material and collaterals in good condition and displayed properly?","photo_required":false,"pts":1}]},{"id":"mstienma_s10","title":"General Observation","items":[{"id":"mstienma_s10_i1","label":"When you say thank you, do the staff respond with \u201cMy Pleasure\u201d?\nWas  the staff pleasant and smiling during your stay?","photo_required":false,"pts":5},{"id":"mstienma_s10_i2","label":"Did the overall dining experience meet or exceed your expectations? Otherwise, please remark.","photo_required":false,"pts":5},{"id":"mstienma_s10_i3","label":"Did the staff give O.R and exact change?","photo_required":false,"pts":5},{"id":"mstienma_s10_i4","label":"Based on this dining experience, would you return as a paying customer?","photo_required":false,"pts":5}]}]'::jsonb,
