ts":5}]},{"id":"mskoobideh_s3","title":"After being seated, did the service staff:","items":[{"id":"mskoobideh_s3_i1","label":"Did the staff arrive within two to three\nminutes to set up your table?","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i2","label":"Did the staff extend a warm greeting and introduce themselves by name?","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i3","label":"Did the staff convey the feeling that\nYou were a valued guest?","photo_required":false,"pts":1},{"id":"mskoobideh_s3_i4","label":"Was your table properly set up?","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i5","label":"Did the staff announce his/her presence?\nDid the staff say, \u201cExcuse me sir / ma\u2019am \n(use guest name if you are familiar)\nyou ordered for <item/s>\u201d, while he / she \nis serving it on your table?","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i6","label":"Serve drinks 3 to 5 minutes?","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i7","label":"Were your beverages served promptly","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i8","label":"Serve food 10 to 15 minutes?","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i9","label":"Did you receive your correct food order?","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i10","label":"Did the staff ask you if he has served all \nyour orders?\n\u201cExcuse me sir / ma\u2019am, have I served \nall your orders?\u201d","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i11","label":"Did the staff anticipate customer needs?\nEx. Extra plate, extra utensils, salt, pepper,\ncheese, and other condiments (especially for\n sharing/group)","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i12","label":"Did the staff thanked you and excused \nhimself?","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i13","label":"If your order took for 15 mins or more, \ndid the employee apologize?","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i14","label":"When you complained about your food, \ndid staff apologize and say he will fix it/ change it?\n\u201cI apologize that you are unhappy, may I change you order? Reheat/ add more syrup?\u201d","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i15","label":"Did the staff remain attentive throughout\nThe dining experience?","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i16","label":"Was the Server wearing complete uniform\nIncluding name tag?","photo_required":false,"pts":5},{"id":"mskoobideh_s3_i17","label":"Was the server approachable & professional in their manner?","photo_required":false,"pts":5}]},{"id":"mskoobideh_s4","title":"During your meal, did your server:","items":[{"id":"mskoobideh_s4_i1","label":"Did staff check back on you to ensure that your meal was satisfactory? Did he announce his presence?\n\u201cExcuse me sir / ma\u2019am, how are you enjoying your food / coffee / drink / meal?\u201d","photo_required":false,"pts":5},{"id":"mskoobideh_s4_i2","label":"Did the server offer refills of water?(if needed)","photo_required":false,"pts":1},{"id":"mskoobideh_s4_i3","label":"When you are waving to a staff, does he acknowledge your call and manage your expectation?","photo_required":false,"pts":5}]},{"id":"mskoobideh_s5","title":"Product Quality","items":[{"id":"mskoobideh_s5_i1","label":"Was your food/pizza temperature appropriate?","photo_required":false,"pts":5},{"id":"mskoobideh_s5_i2","label":"Did it taste good?","photo_required":false,"pts":5},{"id":"mskoobideh_s5_i3","label":"Did it smell good?","photo_required":false,"pts":5},{"id":"mskoobideh_s5_i4","label":"Was your beverage full flavored\n (not watery or flat)","photo_required":false,"pts":5},{"id":"mskoobideh_s5_i5","label":"Was all food served promptly?","photo_required":false,"pts":5},{"id":"mskoobideh_s5_i6","label":"Were your food served according to its \nStandard presentation? \n(Appearance and serving dish)","photo_required":false,"pts":5}]},{"id":"mskoobideh_s6","title":"At the completion of your entr\u00e9e, did your server:","items":[{"id":"mskoobideh_s6_i1","label":"Did the staff clear table of soiled dishes or napkins?\n\u201cExcuse me sir / ma\u2019am would you like me to remove the dishes and table napkins?\u201d","photo_required":false,"pts":5},{"id":"mskoobideh_s6_i2","label":"Did staff clear the table properly and efficiently?\nPay particular attention to how he holds the glasses (in the body and not in the rim), where does he put the utensils (not inside the glass but on the side of the tray), stacking of cups/ saucers and paper napkins (should not be stuffed into glasses or cups).","photo_required":false,"pts":5},{"id":"mskoobideh_s6_i3","label":"Before staff left, did he ask if he can get you anything else?\n\u201cWould you like me to get you something else?","photo_required":false,"pts":5},{"id":"mskoobideh_s6_i4","label":"Did staff excuse him/herself?\n\u201cExcuse me\u201d","photo_required":false,"pts":1}]},{"id":"mskoobideh_s7","title":"Upon leaving the Store:","items":[{"id":"mskoobideh_s7_i1","label":"Did staff thank you politely?\n\u201cThank you for coming.\u201d","photo_required":false,"pts":5},{"id":"mskoobideh_s7_i2","label":"Did staff tell you to visit again?\n\u201c We hope to see you soon.\u201d","photo_required":false,"pts":1}]},{"id":"mskoobideh_s8","title":"Regarding the Manager:","items":[{"id":"mskoobideh_s8_i1","label":"Was the Manager interacting with and directing the staff?","photo_required":false,"pts":5},{"id":"mskoobideh_s8_i2","label":"Was the Manager visiting tables to inquire about satisfaction?","photo_required":false,"pts":5},{"id":"mskoobideh_s8_i3","label":"Did the Manager visit your table?","photo_required":false,"pts":1}]},{"id":"mskoobideh_s9","title":"After being seated, did the service staff:","items":[{"id":"mskoobideh_s9_i1","label":"Is the Outlet clean and orderly? Floors clean & litter free?","photo_required":false,"pts":5},{"id":"mskoobideh_s9_i2","label":"Tables and chairs set orderly?","photo_required":false,"pts":5},{"id":"mskoobideh_s9_i3","label":"Noise level acceptable?","photo_required":false,"pts":1},{"id":"mskoobideh_s9_i4","label":"Music volume & type appropriate?","photo_required":false,"pts":1},{"id":"mskoobideh_s9_i5","label":"Windows and other glass panels are clean?","photo_required":false,"pts":5},{"id":"mskoobideh_s9_i6","label":"Lighting was appropriate?","photo_required":false,"pts":1},{"id":"mskoobideh_s9_i7","label":"Restrooms clean, litter free floors? (if applicable)","photo_required":false,"pts":1},{"id":"mskoobideh_s9_i8","label":"Paper towels and toilet paper stocked? (if applicable)","photo_required":false,"pts":1},{"id":"mskoobideh_s9_i9","label":"Toilets, sinks clean \u2013 good condition? (if applicable)","photo_required":false,"pts":1},{"id":"mskoobideh_s9_i10","label":"Soap dispensers stocked & functional? (if applicable)","photo_required":false,"pts":1},{"id":"mskoobideh_s9_i11","label":"Overall facilities well maintained?","photo_required":false,"pts":5},{"id":"mskoobideh_s9_i12","label":"Signs visible, attractive, maintained?","photo_required":false,"pts":1},{"id":"mskoobideh_s9_i13","label":"Is the store ambient is appropriate/ACU are \nfunctioning?","photo_required":false,"pts":5},{"id":"mskoobideh_s9_i14","label":"Is outlet free from insect/pest infestation?","photo_required":false,"pts":5},{"id":"mskoobideh_s9_i15","label":"Were the advertising material and collaterals in good condition and displayed properly?","photo_required":false,"pts":1}]},{"id":"mskoobideh_s10","title":"General Observation","items":[{"id":"mskoobideh_s10_i1","label":"When you say thank you, do the staff respond with \u201cMy Pleasure\u201d?","photo_required":false,"pts":5},{"id":"mskoobideh_s10_i2","label":"Was staff pleasant and smiling during your stay?","photo_required":false,"pts":5},{"id":"mskoobideh_s10_i3","label":"Did the overall dining experience meet or exceed your expectations?","photo_required":false,"pts":5},{"id":"mskoobideh_s10_i4","label":"Based on this dining experience, would you return as a paying customer?","photo_required":false,"pts":5}]}]'::jsonb,
  true, 'koobideh-kebab', false,
  92.5, true, false, false,
  false, false, '', '',
  true,
  (
    SELECT jsonb_agg(jsonb_build_object('brand_id', b.id, 'brand_name', b.brand_name, 'store_id', s.id, 'store_name', s.store_name))
    FROM public.stores s
    JOIN public.brands b ON b.id = s.brand_id
    WHERE b.brand_name = 'Koobideh Kebabs' AND coalesce(s.is_active, true) AND coalesce(s.kind, 'store') = 'store'
  ),
  now(), now()
WHERE NOT EXISTS (
  SELECT 1 FROM public.audit_templates WHERE title = 'Koobideh Kebabs Mystery Shopper'
);
